#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
CLIP="${1:-box_75}"; CLIP="${CLIP%.npz}"
MOTION="data_demo/${CLIP}.npz"; URDF="data_demo/objects/${CLIP}.urdf"
MASS="${MUJOCO_OBJECT_MASS_OVERRIDE:-1.0}"; [[ "$CLIP" == "box_75" ]] && MASS="${MUJOCO_OBJECT_MASS_OVERRIDE:-2.0}"
[[ -f "$MOTION" && -f "$URDF" && -f "${URDF%.urdf}.obj" ]] || { echo "missing data_demo files for $CLIP" >&2; exit 1; }
PYTHONSAFEPATH=1 PYTHONPATH="src/holosoma${PYTHONPATH:+:$PYTHONPATH}" MUJOCO_GL="${MUJOCO_GL:-glfw}" HOLOSOMA_MUJOCO_WEB_DEMO_OBJECT_CONTACTS="${HOLOSOMA_MUJOCO_WEB_DEMO_OBJECT_CONTACTS:-1}" HOLOSOMA_MUJOCO_CARRY_ARM_OBJECT_CONTACTS="${HOLOSOMA_MUJOCO_CARRY_ARM_OBJECT_CONTACTS:-1}" HOLOSOMA_MUJOCO_LOAD_OBJECT_VISUAL_MESHES="${HOLOSOMA_MUJOCO_LOAD_OBJECT_VISUAL_MESHES:-1}" python -u src/holosoma/holosoma/run_sim.py simulator:mujoco robot:g1_29dof_w_object terrain:terrain_locomotion_plane perception:camera_depth_d435i_mujoco_render_848x480 --training.headless "${HEADLESS:-False}" --simulator.config.sim.fps 500 --simulator.config.sim.control-decimation 10 --simulator.config.sim.substeps 1 --simulator.config.mujoco-backend CLASSIC --robot.object.enabled=True --robot.object.object-urdf-path "$URDF" --robot.object.mujoco-use-training-urdf-scene True --robot.object.mujoco-add-default-actuators True --robot.object.mujoco-copy-joint-defaults-from-robot-xml True --robot.object.mujoco-copy-tendons-from-robot-xml True --robot.object.mujoco-copy-collision-geoms-from-robot-xml True --robot.object.mujoco-copy-contact-pairs-from-robot-xml True --robot.object.mujoco-object-mass-override "$MASS" --simulator.config.bridge.interface lo --simulator.config.bridge.clock-port 5655 --simulator.config.bridge.publish-sim-state=True --simulator.config.bridge.sim-state-port 5657 --simulator.config.bridge.listen-control=True --simulator.config.bridge.control-port 5659 --simulator.config.bridge.publish-perception-obs True --simulator.config.bridge.perception-obs-port 5658 --simulator.config.bridge.publish-perception-obs-shm True --simulator.config.bridge.perception-obs-shm-name depth_img_shm_5657 --simulator.config.bridge.use-zmq-lowcmd True --simulator.config.bridge.ignore-default-idle-command True --simulator.config.bridge.freeze-until-first-command True --motion-init.enabled=True --motion-init.motion-file "$MOTION" --motion-init.mode raw_motion --motion-init.object-name object --perception.camera-source rendered
